79	interface GetCorrectedFileContentResult {
80	  originalContent: string;
81	  correctedContent: string;
82	  fileExists: boolean;
83	  error?: { message: string; code?: string };
84	}
85	
86	export async function getCorrectedFileContent(
87	  config: Config,
88	  filePath: string,
89	  proposedContent: string,
90	  abortSignal: AbortSignal,
91	): Promise<GetCorrectedFileContentResult> {
92	  let originalContent = '';
93	  let fileExists = false;
94	  let correctedContent = proposedContent;
95	
96	  try {
97	    originalContent = await config
98	      .getFileSystemService()
99	      .readTextFile(filePath);
100	    fileExists = true; // File exists and was read
101	  } catch (err) {
102	    if (isNodeError(err) && err.code === 'ENOENT') {
103	      fileExists = false;
104	      originalContent = '';
105	    } else {
106	      // File exists but could not be read (permissions, etc.)
107	      fileExists = true; // Mark as existing but problematic
108	      originalContent = ''; // Can't use its content
109	      const error = {
110	        message: getErrorMessage(err),
111	        code: isNodeError(err) ? err.code : undefined,
112	      };
113	      // Return early as we can't proceed with content correction meaningfully
114	      return { originalContent, correctedContent, fileExists, error };
115	    }
116	  }
117	
118	  // If readError is set, we have returned.
119	  // So, file was either read successfully (fileExists=true, originalContent set)
120	  // or it was ENOENT (fileExists=false, originalContent='').
121	
122	  if (fileExists) {
123	    // This implies originalContent is available
124	    const { params: correctedParams } = await ensureCorrectEdit(
125	      filePath,
126	      originalContent,
127	      {
128	        old_string: originalContent, // Treat entire current content as old_string
129	        new_string: proposedContent,
130	        file_path: filePath,
131	      },
132	      config.getGeminiClient(),
133	      config.getBaseLlmClient(),
134	      abortSignal,
135	      config.getDisableLLMCorrection(),
136	    );
137	    correctedContent = correctedParams.new_string;
138	  } else {
139	    // This implies new file (ENOENT)
140	    correctedContent = await ensureCorrectFileContent(
141	      proposedContent,
142	      config.getBaseLlmClient(),
143	      abortSignal,
144	      config.getDisableLLMCorrection(),
145	    );
146	  }
147	  return { originalContent, correctedContent, fileExists };
148	}
