171	    return [{ path: this.resolvedPath }];
172	  }
173	
174	  override getDescription(): string {
175	    const relativePath = makeRelative(
176	      this.resolvedPath,
177	      this.config.getTargetDir(),
178	    );
179	    return `Writing to ${shortenPath(relativePath)}`;
