181	
182	  protected override async getConfirmationDetails(
183	    abortSignal: AbortSignal,
184	  ): Promise<ToolCallConfirmationDetails | false> {
185	    if (this.config.getApprovalMode() === ApprovalMode.AUTO_EDIT) {
186	      return false;
187	    }
188	
189	    const correctedContentResult = await getCorrectedFileContent(
