195	
196	    if (correctedContentResult.error) {
197	      // If file exists but couldn't be read, we can't show a diff for confirmation.
198	      return false;
199	    }
200	
201	    const { originalContent, correctedContent } = correctedContentResult;
202	    const relativePath = makeRelative(
203	      this.resolvedPath,
204	      this.config.getTargetDir(),
205	    );
206	    const fileName = path.basename(this.resolvedPath);
207	
208	    const fileDiff = Diff.createPatch(
209	      fileName,
210	      originalContent, // Original content (empty if new file or unreadable)
211	      correctedContent, // Content after potential correction
212	      'Current',
213	      'Proposed',
214	      DEFAULT_DIFF_OPTIONS,
215	    );
216	
217	    const ideClient = await IdeClient.getInstance();
218	    const ideConfirmation =
219	      this.config.getIdeMode() && ideClient.isDiffingEnabled()
220	        ? ideClient.openDiff(this.resolvedPath, correctedContent)
221	        : undefined;
222	
223	    const confirmationDetails: ToolEditConfirmationDetails = {
224	      type: 'edit',
225	      title: `Confirm Write: ${shortenPath(relativePath)}`,
226	      fileName,
227	      filePath: this.resolvedPath,
228	      fileDiff,
229	      originalContent,
230	      newContent: correctedContent,
231	      onConfirm: async (_outcome: ToolConfirmationOutcome) => {
232	        // Mode transitions (e.g. AUTO_EDIT) and policy updates are now
