33	/**
34	 * Parameters for the GrepTool
35	 */
36	export interface GrepToolParams {
37	  /**
38	   * The regular expression pattern to search for in file contents
39	   */
40	  pattern: string;
41	
42	  /**
43	   * The directory to search in (optional, defaults to current directory relative to root)
44	   */
45	  dir_path?: string;
46	
47	  /**
48	   * File pattern to include in the search (e.g. "*.js", "*.{ts,tsx}")
49	   */
50	  include?: string;
51	
52	  /**
53	   * Optional: A regular expression pattern to exclude from the search results.
54	   */
55	  exclude_pattern?: string;
56	
57	  /**
58	   * Optional: If true, only the file paths of the matches will be returned.
59	   */
60	  names_only?: boolean;
61	
62	  /**
63	   * Optional: Maximum number of matches to return per file. Use this to prevent being overwhelmed by repetitive matches in large files.
64	   */
65	  max_matches_per_file?: number;
66	
67	  /**
68	   * Optional: Maximum number of total matches to return. Use this to limit the overall size of the response. Defaults to 100 if omitted.
69	   */
70	  total_max_matches?: number;
71	}
72	
73	/**
74	 * Result object for a single grep match
75	 */
76	interface GrepMatch {
77	  filePath: string;
78	  lineNumber: number;
79	  line: string;
80	}
81	
82	class GrepToolInvocation extends BaseToolInvocation<
83	  GrepToolParams,
84	  ToolResult
85	> {
86	  private readonly fileExclusions: FileExclusions;
87	
88	  constructor(
89	    private readonly config: Config,
90	    params: GrepToolParams,
91	    messageBus: MessageBus,
92	    _toolName?: string,
93	    _toolDisplayName?: string,
94	  ) {
95	    super(params, messageBus, _toolName, _toolDisplayName);
96	    this.fileExclusions = config.getFileExclusions();
97	  }
98	
99	  /**
100	   * Parses a single line of grep-like output (git grep, system grep).
101	   * Expects format: filePath:lineNumber:lineContent
102	   * @param {string} line The line to parse.
103	   * @param {string} basePath The absolute directory for path resolution.
104	   * @returns {GrepMatch | null} Parsed match or null if malformed.
105	   */
106	  private parseGrepLine(line: string, basePath: string): GrepMatch | null {
107	    if (!line.trim()) return null;
108	
109	    // Use regex to locate the first occurrence of :<digits>:
110	    // This allows filenames to contain colons, as long as they don't look like :<digits>:
111	    // Note: This regex assumes filenames do not contain colons, or at least not followed by digits.
112	    const match = line.match(/^(.+?):(\d+):(.*)$/);
113	    if (!match) return null;
114	
115	    const [, filePathRaw, lineNumberStr, lineContent] = match;
116	    const lineNumber = parseInt(lineNumberStr, 10);
117	
118	    if (!isNaN(lineNumber)) {
119	      const absoluteFilePath = path.resolve(basePath, filePathRaw);
120	      const relativeCheck = path.relative(basePath, absoluteFilePath);
121	      if (
122	        relativeCheck === '..' ||
123	        relativeCheck.startsWith(`..${path.sep}`) ||
124	        path.isAbsolute(relativeCheck)
125	      ) {
126	        return null;
127	      }
128	
129	      const relativeFilePath = path.relative(basePath, absoluteFilePath);
130	
131	      return {
132	        filePath: relativeFilePath || path.basename(absoluteFilePath),
133	        lineNumber,
134	        line: lineContent,
135	      };
136	    }
137	    return null;
138	  }
139	
140	  async execute(signal: AbortSignal): Promise<ToolResult> {
141	    try {
142	      const workspaceContext = this.config.getWorkspaceContext();
143	      const pathParam = this.params.dir_path;
144	
145	      let searchDirAbs: string | null = null;
146	      if (pathParam) {
147	        searchDirAbs = path.resolve(this.config.getTargetDir(), pathParam);
148	        const validationError = this.config.validatePathAccess(
149	          searchDirAbs,
150	          'read',
151	        );
152	        if (validationError) {
153	          return {
154	            llmContent: validationError,
155	            returnDisplay: 'Error: Path not in workspace.',
156	            error: {
157	              message: validationError,
158	              type: ToolErrorType.PATH_NOT_IN_WORKSPACE,
159	            },
160	          };
161	        }
162	
163	        try {
164	          const stats = await fsPromises.stat(searchDirAbs);
165	          if (!stats.isDirectory()) {
166	            return {
167	              llmContent: `Path is not a directory: ${searchDirAbs}`,
168	              returnDisplay: 'Error: Path is not a directory.',
169	              error: {
170	                message: `Path is not a directory: ${searchDirAbs}`,
171	                type: ToolErrorType.PATH_IS_NOT_A_DIRECTORY,
172	              },
173	            };
174	          }
175	        } catch (error: unknown) {
176	          if (isNodeError(error) && error.code === 'ENOENT') {
177	            return {
178	              llmContent: `Path does not exist: ${searchDirAbs}`,
179	              returnDisplay: 'Error: Path does not exist.',
180	              error: {
181	                message: `Path does not exist: ${searchDirAbs}`,
182	                type: ToolErrorType.FILE_NOT_FOUND,
183	              },
184	            };
185	          }
186	          const errorMessage = getErrorMessage(error);
187	          return {
188	            llmContent: `Failed to access path stats for ${searchDirAbs}: ${errorMessage}`,
189	            returnDisplay: 'Error: Failed to access path.',
190	            error: {
191	              message: `Failed to access path stats for ${searchDirAbs}: ${errorMessage}`,
192	              type: ToolErrorType.GREP_EXECUTION_ERROR,
193	            },
194	          };
195	        }
196	      }
197	
198	      const searchDirDisplay = pathParam || '.';
199	
200	      // Determine which directories to search
201	      let searchDirectories: readonly string[];
202	      if (searchDirAbs === null) {
203	        // No path specified - search all workspace directories
204	        searchDirectories = workspaceContext.getDirectories();
205	      } else {
206	        // Specific path provided - search only that directory
207	        searchDirectories = [searchDirAbs];
208	      }
209	
210	      // Collect matches from all search directories
211	      let allMatches: GrepMatch[] = [];
212	      const totalMaxMatches =
