39	async function resolveExistingRgPath(): Promise<string | null> {
40	  const binDir = Storage.getGlobalBinDir();
41	  for (const fileName of getRgCandidateFilenames()) {
42	    const candidatePath = path.join(binDir, fileName);
43	    if (await fileExists(candidatePath)) {
44	      return candidatePath;
45	    }
46	  }
47	  return null;
48	}
49	
50	let ripgrepAcquisitionPromise: Promise<string | null> | null = null;
51	
52	async function ensureRipgrepAvailable(): Promise<string | null> {
53	  const existingPath = await resolveExistingRgPath();
54	  if (existingPath) {
55	    return existingPath;
56	  }
57	  if (!ripgrepAcquisitionPromise) {
58	    ripgrepAcquisitionPromise = (async () => {
59	      try {
60	        await downloadRipGrep(Storage.getGlobalBinDir());
61	        return await resolveExistingRgPath();
62	      } finally {
63	        ripgrepAcquisitionPromise = null;
64	      }
65	    })();
66	  }
67	  return ripgrepAcquisitionPromise;
68	}
