import * as Diff from 'diff';

/**
 * Produces a context-aware snippet of the `modified` content that shows only
 * the lines that changed relative to `original`, plus a configurable number of
 * surrounding context lines.
 *
 * Behavior:
 * - If `original` is empty (a brand new file) or the content is unchanged, the
 *   full `modified` content is returned.
 * - Otherwise only changed lines and up to `contextLines` lines of surrounding
 *   context are returned.
 * - Overlapping (or adjacent) context windows are merged. Windows separated by
 *   omitted content are joined with an '...' marker.
 * - When content is omitted before the first change or after the last change,
 *   the snippet is prefixed/suffixed with '...'.
 * - Deletions are represented by showing their surrounding context, again using
 *   '...' for any omitted content.
 *
 * @param original The original content.
 * @param modified The modified content.
 * @param contextLines The number of context lines to show around each change.
 * @returns A snippet of the modified content.
 */
export function getDiffContextSnippet(
  original: string,
  modified: string,
  contextLines = 5,
): string {
  // A brand new file (no original content) or an unchanged file has no
  // meaningful diff context to compute, so return the full modified content.
  if (original === '' || original === modified) {
    return modified;
  }

  const modifiedLines = modified.split('\n');
  const totalLines = modifiedLines.length;

  const parts = Diff.diffLines(original, modified);

  // Track which indices (0-based) of the modified content changed.
  const changedLineIndices = new Set<number>();
  let modIndex = 0;

  for (const part of parts) {
    const lineCount =
      part.count ??
      (part.value === ''
        ? 0
        : part.value.replace(/\n$/, '').split('\n').length);

    if (part.added) {
      for (let i = 0; i < lineCount; i++) {
        if (modIndex + i < totalLines) {
          changedLineIndices.add(modIndex + i);
        }
      }
      modIndex += lineCount;
    } else if (part.removed) {
      // Deleted lines do not exist in the modified content, but we still want
      // to surface the surrounding lines around the point of deletion.
      const boundary = Math.min(modIndex, totalLines - 1);
      changedLineIndices.add(boundary);
      if (boundary - 1 >= 0) {
        changedLineIndices.add(boundary - 1);
      }
    } else {
      // Unchanged block.
      modIndex += lineCount;
    }
  }

  if (changedLineIndices.size === 0) {
    return modified;
  }

  const sortedIndices = Array.from(changedLineIndices).sort((a, b) => a - b);

  // Build merged intervals of [start, end], each expanded by `contextLines`.
  // Adjacent or overlapping windows are merged so their context isn't
  // duplicated or broken up by spurious '...' markers.
  const intervals: Array<[number, number]> = [];
  for (const index of sortedIndices) {
    const start = Math.max(0, index - contextLines);
    const end = Math.min(totalLines - 1, index + contextLines);
    const last = intervals[intervals.length - 1];
    if (last && start <= last[1] + 1) {
      last[1] = Math.max(last[1], end);
    } else {
      intervals.push([start, end]);
    }
  }

  const snippetParts: string[] = [];

  // Content omitted before the first shown line.
  if (intervals[0][0] > 0) {
    snippetParts.push('...');
  }

  intervals.forEach(([start, end], i) => {
    // Distant context windows are separated by an ellipsis.
    if (i > 0) {
      snippetParts.push('...');
    }
    for (let line = start; line <= end; line++) {
      snippetParts.push(modifiedLines[line]);
    }
  });

  // Content omitted after the last shown line.
  if (intervals[intervals.length - 1][1] < totalLines - 1) {
    snippetParts.push('...');
  }

  return snippetParts.join('\n');
}
