[metadata] {"type": "create", "filePath": "/workspace/repo/packages/core/src/tools/diff-utils.tmpcheck.test.ts", "content": "import { describe, it, expect } from 'vitest';
import { getDiffContextSnippet } from './diff-utils.js';

describe('getDiffContextSnippet sanity', () => {
  it('returns full content for new file', () => {
    expect(getDiffContextSnippet('', 'a\nb\nc')).toBe('a\nb\nc');
  });
  it('returns full content when unchanged', () => {
    expect(getDiffContextSnippet('a\nb', 'a\nb')).toBe('a\nb');
  });
  it('snippets a large file with ellipsis around a single change', () => {
    const orig = Array.from({ length: 20 }, (_, i) => `line${i + 1}`).join('\n');
    const mod = orig.replace('line10', 'CHANGED');
    const snip = getDiffContextSnippet(orig, mod, 2);
    // Change at line 10 (index 9), context 2 => lines 8..12 shown, ellipsis both sides
    expect(snip).toBe('...\nline8\nline9\nCHANGED\nline11\nline12\n...');
  });
  it('separates distant changes with ellipsis and merges near ones', () => {
    const orig = Array.from({ length: 30 }, (_, i) => `L${i + 1}`).join('\n');
    let mod = orig.replace('L5', 'A');
    mod = mod.replace('L25', 'B');
    const snip = getDiffContextSnippet(orig, mod, 1);
    expect(snip).toContain('A');
    expect(snip).toContain('B');
    // ellipsis between and around
    const ellipsisCount = (snip.match(/\.\.\./g) || []).length;
    expect(ellipsisCount).toBe(3); // before, between, after
  });
  it('shows context around a deletion', () => {
    const orig = 'a\nb\nDELETED\nc\nd';
    const mod = 'a\nb\nc\nd';
    const snip = getDiffContextSnippet(orig, mod, 1);
    expect(snip).not.toContain('DELETED');
    expect(snip).toContain('b');
    expect(snip).toContain('c');
  });
});
